			case "init":
				opts.init = true
			case "list":
				opts.list = true
			case "path":
				if hasVal {
					opts.path = val
				} else if i+1 < len(args) {
					i++
					opts.path = args[i]
				} else {
					return nil, nil, fmt.Errorf("flag needs an argument: --path")
				}
			case "regex":
				opts.regex = true
			case "rm":
				if hasVal {
					opts.rm = val
				} else if i+1 < len(args) {
					i++
					opts.rm = args[i]
				} else {
					return nil, nil, fmt.Errorf("flag needs an argument: --rm")
				}
			case "search":
				if hasVal {
					opts.search = val
				} else if i+1 < len(args) {
					i++
					opts.search = args[i]
				} else {
					return nil, nil, fmt.Errorf("flag needs an argument: --search")
				}
			case "tag":
				if hasVal {
					opts.tag = val
				} else if i+1 < len(args) {
					i++
					opts.tag = args[i]
				} else {
					return nil, nil, fmt.Errorf("flag needs an argument: --tag")
				}
			case "tags":
				opts.tags = true
			case "update":
				opts.update = true
			case "version":
				opts.version = true
			default:
				return nil, nil, fmt.Errorf("unknown flag: --%s", flagName)
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			flags := arg[1:]
			for j := 0; j < len(flags); j++ {
				f := flags[j]
				switch f {
				case 'a':
					opts.all = true
				case 'b':
					opts.brief = true
				case 'c':
					opts.colorize = true
				case 'd':
					opts.directories = true
				case 'e':
					if j+1 < len(flags) {
