						break
					} else if i+1 < len(args) {
						i++
						opts.edit = args[i]
					} else {
						return nil, nil, fmt.Errorf("flag needs an argument: 'e'")
					}
				case 'h':
					opts.help = true
				case 'l':
					opts.list = true
				case 'p':
					if j+1 < len(flags) {
						opts.path = flags[j+1:]
						break
					} else if i+1 < len(args) {
						i++
						opts.path = args[i]
					} else {
						return nil, nil, fmt.Errorf("flag needs an argument: 'p'")
