func loadConfig() (*Config, error) {
	configPath := findConfigPath()
	if configPath == "" {
		// Run installer prompt
		createdPath, err := runInstaller()
		if err != nil {
			return nil, &ExitError{Code: 1, Message: fmt.Sprintf("failed to create config: %v", err), ToStderr: true}
		}
		if createdPath == "" {
			os.Exit(0)
		}
		configPath = createdPath
	}

	data, err := os.ReadFile(configPath)
	if err != nil {
		return nil, &ExitError{Code: 1, Message: fmt.Sprintf("failed to load config: %v", err), ToStderr: true}
	}

	cfg, err := parseYAMLConfig(data)
	if err != nil {
		return nil, &ExitError{Code: 1, Message: fmt.Sprintf("failed to load config: could not unmarshal yaml: %v", err), ToStderr: true}
	}
	cfg.Path = configPath

	// Validate config
	if len(cfg.Cheatpaths) == 0 {
		return nil, &ExitError{Code: 1, Message: "failed to load config: config error: no cheatpaths specified", ToStderr: true}
	}

	names := make(map[string]bool)
	var validCheatpaths []Cheatpath
	for _, cp := range cfg.Cheatpaths {
		if cp.Name == "" {
			return nil, &ExitError{Code: 1, Message: "failed to load config: config error: cheatpath name cannot be empty", ToStderr: true}
		}
		if names[cp.Name] {
			return nil, &ExitError{Code: 1, Message: fmt.Sprintf("failed to load config: config error: cheatpath name is not unique: %s", cp.Name), ToStderr: true}
		}
		names[cp.Name] = true

		expandedPath := expandPath(cp.Path)
		if _, err := os.Stat(expandedPath); err != nil {
			fmt.Fprintf(os.Stderr, "WARNING: cheatpath '%s' does not exist, skipping\n", expandedPath)
			continue
		}
		cp.Path = expandedPath
		validCheatpaths = append(validCheatpaths, cp)
	}

	if len(validCheatpaths) == 0 {
		return nil, &ExitError{Code: 1, Message: "failed to load config: config error: no cheatpaths specified", ToStderr: true}
	}
	cfg.Cheatpaths = validCheatpaths

	return cfg, nil
}

func findConfigPath() string {
	if env := os.Getenv("CHEAT_CONFIG_PATH"); env != "" {
		if _, err := os.Stat(env); err == nil {
			return env
		}
		return ""
	}

	home := getHomeDir()
	candidates := []string{}
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		candidates = append(candidates, filepath.Join(xdg, "cheat", "conf.yml"))
	}
	if home != "" {
		candidates = append(candidates, filepath.Join(home, ".config", "cheat", "conf.yml"))
		candidates = append(candidates, filepath.Join(home, ".cheat", "conf.yml"))
	}
	candidates = append(candidates, "/etc/cheat/conf.yml")

	for _, c := range candidates {
		if _, err := os.Stat(c); err == nil {
			return c
		}
	}
	return ""
}

