func main() {
	app := NewApp()
	if err := app.Run(os.Args); err != nil {
		if exitErr, ok := err.(*ExitError); ok {
			if exitErr.Message != "" {
				if exitErr.ToStderr {
					fmt.Fprintln(os.Stderr, exitErr.Message)
				} else {
					fmt.Fprintln(os.Stdout, exitErr.Message)
				}
			}
			os.Exit(exitErr.Code)
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

type ExitError struct {
	Code     int
	Message  string
	ToStderr bool
}

func (e *ExitError) Error() string {
	return e.Message
}

type App struct{}

func NewApp() *App {
	return &App{}
}

func (a *App) Run(args []string) error {
	// Parse CLI flags and commands
	opts, positional, err := parseFlags(args[1:])
	if err != nil {
		return &ExitError{Code: 1, Message: err.Error(), ToStderr: true}
	}

	if opts.version {
		fmt.Println(version)
		return nil
	}

	if opts.help {
		printHelp()
		return nil
	}

	if opts.init {
		printInit()
		return nil
	}

	if opts.completion != "" {
		return handleCompletion(opts.completion)
	}

	if len(args) > 1 && args[1] == "__complete" {
		return handleCobraComplete(args[2:])
	}

	// For all other commands, load config
	cfg, err := loadConfig()
	if err != nil {
		return err
	}

	if opts.conf {
		fmt.Println(cfg.Path)
		return nil
	}

	// Add directory-scoped cheatpath (.cheat)
	addDirectoryScopedCheatpath(cfg)

	if opts.directories {
		return printDirectories(cfg, opts)
	}

	if opts.update {
		return handleUpdate(cfg, opts)
	}

	// Load cheatsheets
	sheets, err := loadCheatsheets(cfg)
	if err != nil {
		return &ExitError{Code: 1, Message: err.Error(), ToStderr: true}
	}

	if opts.tags {
		return printTags(sheets, cfg, opts)
	}

	if opts.edit != "" {
		return handleEdit(cfg, sheets, opts.edit, opts.path)
	}

	if opts.rm != "" {
		return handleRm(cfg, sheets, opts.rm, opts.path)
	}

	if opts.list || opts.brief {
		return printList(sheets, opts, positional, cfg)
	}

	if opts.search != "" {
		return handleSearch(sheets, opts, cfg)
	}

	if len(positional) == 0 {
		printHelp()
		return nil
	}

	if len(positional) > 1 {
		return &ExitError{Code: 1, Message: fmt.Sprintf("accepts at most 1 arg(s), received %d", len(positional)), ToStderr: true}
	}

	return handleView(sheets, positional[0], opts, cfg)
}

type Options struct {
	all         bool
	brief       bool
	colorize    bool
	completion  string
	conf        bool
	directories bool
	edit        string
	help        bool
	init        bool
	list        bool
	path        string
	regex       bool
	rm          string
	search      string
	tag         string
	tags        bool
	update      bool
	version     bool
}

func parseFlags(args []string) (*Options, []string, error) {
	opts := &Options{}
	var positional []string

	for i := 0; i < len(args); i++ {
		arg := args[i]

		if arg == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}

		if strings.HasPrefix(arg, "--") {
			flagName := arg[2:]
			var val string
			hasVal := false
			if idx := strings.IndexByte(flagName, '='); idx != -1 {
				val = flagName[idx+1:]
				flagName = flagName[:idx]
				hasVal = true
			}

			switch flagName {
			case "all":
				opts.all = true
			case "brief":
				opts.brief = true
			case "colorize":
				opts.colorize = true
			case "completion":
				if hasVal {
					opts.completion = val
				} else if i+1 < len(args) {
					i++
					opts.completion = args[i]
				} else {
					return nil, nil, fmt.Errorf("flag needs an argument: --completion")
				}
			case "conf":
				opts.conf = true
			case "directories":
				opts.directories = true
			case "edit":
				if hasVal {
					opts.edit = val
				} else if i+1 < len(args) {
					i++
					opts.edit = args[i]
				} else {
					return nil, nil, fmt.Errorf("flag needs an argument: --edit")
				}
			case "help":
				opts.help = true
			case "init":
				opts.init = true
			case "list":
				opts.list = true
			case "path":
				if hasVal {
					opts.path = val
				} else if i+1 < len(args) {
					i++
					opts.path = args[i]
				} else {
					return nil, nil, fmt.Errorf("flag needs an argument: --path")
				}
			case "regex":
				opts.regex = true
			case "rm":
				if hasVal {
					opts.rm = val
				} else if i+1 < len(args) {
					i++
					opts.rm = args[i]
				} else {
					return nil, nil, fmt.Errorf("flag needs an argument: --rm")
				}
			case "search":
				if hasVal {
					opts.search = val
				} else if i+1 < len(args) {
					i++
					opts.search = args[i]
				} else {
					return nil, nil, fmt.Errorf("flag needs an argument: --search")
				}
			case "tag":
				if hasVal {
					opts.tag = val
				} else if i+1 < len(args) {
					i++
					opts.tag = args[i]
				} else {
					return nil, nil, fmt.Errorf("flag needs an argument: --tag")
				}
			case "tags":
				opts.tags = true
			case "update":
				opts.update = true
			case "version":
				opts.version = true
			default:
				return nil, nil, fmt.Errorf("unknown flag: --%s", flagName)
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			flags := arg[1:]
			for j := 0; j < len(flags); j++ {
				f := flags[j]
				switch f {
				case 'a':
					opts.all = true
				case 'b':
					opts.brief = true
				case 'c':
					opts.colorize = true
				case 'd':
					opts.directories = true
				case 'e':
					if j+1 < len(flags) {
						opts.edit = flags[j+1:]
						break
					} else if i+1 < len(args) {
						i++
						opts.edit = args[i]
					} else {
						return nil, nil, fmt.Errorf("flag needs an argument: 'e'")
					}
				case 'h':
					opts.help = true
				case 'l':
					opts.list = true
				case 'p':
					if j+1 < len(flags) {
						opts.path = flags[j+1:]
						break
					} else if i+1 < len(args) {
						i++
						opts.path = args[i]
					} else {
						return nil, nil, fmt.Errorf("flag needs an argument: 'p'")
					}
				case 'r':
					opts.regex = true
				case 's':
					if j+1 < len(flags) {
						opts.search = flags[j+1:]
						break
					} else if i+1 < len(args) {
						i++
						opts.search = args[i]
					} else {
						return nil, nil, fmt.Errorf("flag needs an argument: 's'")
					}
				case 't':
					if j+1 < len(flags) {
						opts.tag = flags[j+1:]
						break
					} else if i+1 < len(args) {
						i++
						opts.tag = args[i]
					} else {
						return nil, nil, fmt.Errorf("flag needs an argument: 't'")
					}
				case 'T':
					opts.tags = true
				case 'u':
					opts.update = true
				case 'v':
					opts.version = true
				default:
					return nil, nil, fmt.Errorf("unknown shorthand flag: '%c' in -%s", f, flags)
				}
			}
		} else {
			positional = append(positional, arg)
		}
	}

	return opts, positional, nil
}

func printHelp() {
	helpText := `cheat allows you to create and view interactive cheatsheets on the
command-line. It was designed to help remind *nix system administrators of
options for commands that they use frequently, but not frequently enough to
remember.

Usage:
  cheat [cheatsheet] [flags]

Examples:
  To initialize a config file:
    mkdir -p ~/.config/cheat && cheat --init > ~/.config/cheat/conf.yml

  To view the tar cheatsheet:
    cheat tar

  To edit (or create) the foo cheatsheet:
    cheat -e foo

  To edit (or create) the foo/bar cheatsheet on the "work" cheatpath:
    cheat -p work -e foo/bar

  To view all cheatsheet directories:
    cheat -d

  To list all available cheatsheets:
    cheat -l

  To briefly list all cheatsheets whose titles match "apt":
    cheat -b apt

  To list all tags in use:
    cheat -T

  To list available cheatsheets that are tagged as "personal":
    cheat -l -t personal

  To search for "ssh" among all cheatsheets, and colorize matches:
    cheat -c -s ssh

  To search (by regex) for cheatsheets that contain an IP address:
    cheat -c -r -s '(?:[0-9]{1,3}\.){3}[0-9]{1,3}'

  To remove (delete) the foo/bar cheatsheet:
    cheat --rm foo/bar

  To update all git-backed cheatpaths:
    cheat --update

  To view the configuration file path:
    cheat --conf

  To generate shell completions (bash, zsh, fish, powershell):
    cheat --completion bash

Flags:
  -a, --all                Search among all cheatpaths
  -b, --brief              List cheatsheets without file paths
  -c, --colorize           Colorize output
      --completion shell   Generate shell completion script (shell: bash, zsh, fish, powershell)
      --conf               Display the config file path
  -d, --directories        List cheatsheet directories
  -e, --edit cheatsheet    Edit cheatsheet
  -h, --help               help for cheat
      --init               Write a default config file to stdout
  -l, --list               List cheatsheets
  -p, --path name          Return only sheets found on cheatpath name
  -r, --regex              Treat search <phrase> as a regex
      --rm cheatsheet      Remove (delete) cheatsheet
  -s, --search phrase      Search cheatsheets for phrase
  -t, --tag tag            Return only sheets matching tag
  -T, --tags               List all tags in use
  -u, --update             Update git-backed cheatpaths
  -v, --version            Print the version number
`
	fmt.Print(helpText)
}

