func getHomeDir() string {
	if u, err := user.Current(); err == nil && u.HomeDir != "" {
		return u.HomeDir
	}
	if h := os.Getenv("HOME"); h != "" {
		return h
	}
	return ""
}

func loadConfig() (*Config, error) {
	configPath := findConfigPath()
	if configPath == "" {
		// Run installer prompt
		createdPath, err := runInstaller()
		if err != nil {
			return nil, &ExitError{Code: 1, Message: fmt.Sprintf("failed to create config: %v", err), ToStderr: true}
		}
		if createdPath == "" {
			os.Exit(0)
		}
		configPath = createdPath
	}

	data, err := os.ReadFile(configPath)
	if err != nil {
		return nil, &ExitError{Code: 1, Message: fmt.Sprintf("failed to load config: %v", err), ToStderr: true}
	}

	cfg, err := parseYAMLConfig(data)
	if err != nil {
		return nil, &ExitError{Code: 1, Message: fmt.Sprintf("failed to load config: could not unmarshal yaml: %v", err), ToStderr: true}
	}
	cfg.Path = configPath

	// Validate config
	if len(cfg.Cheatpaths) == 0 {
		return nil, &ExitError{Code: 1, Message: "failed to load config: config error: no cheatpaths specified", ToStderr: true}
	}

	names := make(map[string]bool)
	var validCheatpaths []Cheatpath
	for _, cp := range cfg.Cheatpaths {
		if cp.Name == "" {
			return nil, &ExitError{Code: 1, Message: "failed to load config: config error: cheatpath name cannot be empty", ToStderr: true}
		}
		if names[cp.Name] {
			return nil, &ExitError{Code: 1, Message: fmt.Sprintf("failed to load config: config error: cheatpath name is not unique: %s", cp.Name), ToStderr: true}
		}
		names[cp.Name] = true

		expandedPath := expandPath(cp.Path)
		if _, err := os.Stat(expandedPath); err != nil {
			fmt.Fprintf(os.Stderr, "WARNING: cheatpath '%s' does not exist, skipping\n", expandedPath)
			continue
		}
		cp.Path = expandedPath
		validCheatpaths = append(validCheatpaths, cp)
	}

	if len(validCheatpaths) == 0 {
		return nil, &ExitError{Code: 1, Message: "failed to load config: config error: no cheatpaths specified", ToStderr: true}
	}
	cfg.Cheatpaths = validCheatpaths

	return cfg, nil
}

func findConfigPath() string {
	if env := os.Getenv("CHEAT_CONFIG_PATH"); env != "" {
		if _, err := os.Stat(env); err == nil {
			return env
		}
		return ""
	}

	home := getHomeDir()
	candidates := []string{}
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		candidates = append(candidates, filepath.Join(xdg, "cheat", "conf.yml"))
	}
	if home != "" {
		candidates = append(candidates, filepath.Join(home, ".config", "cheat", "conf.yml"))
		candidates = append(candidates, filepath.Join(home, ".cheat", "conf.yml"))
	}
	candidates = append(candidates, "/etc/cheat/conf.yml")

	for _, c := range candidates {
		if _, err := os.Stat(c); err == nil {
			return c
		}
	}
	return ""
}

func runInstaller() (string, error) {
	fmt.Print("A config file was not found. Would you like to create one now? [Y/n]: ")
	reader := bufio.NewReader(os.Stdin)
	ans, err := reader.ReadString('\n')
	if err != nil {
		return "", fmt.Errorf("failed to prompt: %v", err)
	}
	ans = strings.TrimSpace(strings.ToLower(ans))
	if ans != "" && ans != "y" && ans != "yes" {
		return "", nil
	}

	fmt.Print("Would you like to download the community cheatsheets? [Y/n]: ")
	ans2, err := reader.ReadString('\n')
	if err != nil {
		return "", fmt.Errorf("failed to prompt: %v", err)
	}
	ans2 = strings.TrimSpace(strings.ToLower(ans2))

	home := getHomeDir()
	configDir := filepath.Join(home, ".config", "cheat")
	if err := os.MkdirAll(configDir, 0755); err != nil {
		return "", fmt.Errorf("failed to create config dir: %v", err)
	}
	confPath := filepath.Join(configDir, "conf.yml")

	// Generate conf.yml
	var buf bytes.Buffer
	initTmpl := fmt.Sprintf(`---
# The editor to use with 'cheat -e <sheet>'. Overridden by $VISUAL or $EDITOR.
editor: EDITOR_PATH

# Should 'cheat' always colorize output?
colorize: false

# Which 'chroma' colorscheme should be applied to the output?
# Options are available here:
#   https://github.com/alecthomas/chroma/tree/master/styles
style: monokai

# Which 'chroma' "formatter" should be applied?
# One of: "terminal", "terminal256", "terminal16m"
formatter: terminal256

# Through which pager should output be piped?
# 'less -FRX' is recommended on Unix systems
# 'more' is recommended on Windows
pager: cat

# The paths at which cheatsheets are available. Tags associated with a cheatpath
# are automatically attached to all cheatsheets residing on that path.
#
# Whenever cheatsheets share the same title (like 'tar'), the most local
# cheatsheets (those which come later in this file) take precedence over the
# less local sheets. This allows you to create your own "overides" for
# "upstream" cheatsheets.
#
# But what if you want to view the "upstream" cheatsheets instead of your own?
# Cheatsheets may be filtered by 'tags' in combination with the '--tag' flag.
# 
# Example: 'cheat tar --tag=community' will display the 'tar' cheatsheet that
# is tagged as 'community' rather than your own.
#
# Paths that come earlier are considered to be the most "global", and paths
# that come later are considered to be the most "local". The most "local" paths
# take precedence.
#
# See: https://github.com/cheat/cheat/blob/master/doc/cheat.1.md#cheatpaths
cheatpaths:

  # Cheatsheets that are tagged "personal" are stored here by default:
  - name: personal
    path: %s/.config/cheat/cheatsheets/personal
    tags: [ personal ]
    readonly: false

  # Cheatsheets that are tagged "work" are stored here by default:
  - name: work
    path: %s/.config/cheat/cheatsheets/work
    tags: [ work ]
    readonly: false

  # Community cheatsheets (https://github.com/cheat/cheatsheets):
  # To install: git clone https://github.com/cheat/cheatsheets %s/.config/cheat/cheatsheets/community
  #- name: community
  #  path: %s/.config/cheat/cheatsheets/community
  #  tags: [ community ]
  #  readonly: true

  # You can also use glob patterns to automatically load cheatsheets from all
  # directories that match.
  #
  # Example: overload cheatsheets for projects under ~/src/github.com/example/*/
  #- name: example-projects
  #  path: ~/src/github.com/example/**/.cheat
  #  tags: [ example ]
  #  readonly: true
`, home, home, home, home)
	buf.WriteString(initTmpl)

	if err := os.WriteFile(confPath, buf.Bytes(), 0644); err != nil {
		return "", fmt.Errorf("failed to write conf.yml: %v", err)
	}

	// Create cheatsheet dirs
	os.MkdirAll(filepath.Join(configDir, "cheatsheets", "personal"), 0755)
	os.MkdirAll(filepath.Join(configDir, "cheatsheets", "work"), 0755)

	if ans2 == "" || ans2 == "y" || ans2 == "yes" {
		commDir := filepath.Join(configDir, "cheatsheets", "community")
		cmd := exec.Command("git", "clone", "https://github.com/cheat/cheatsheets", commDir)
		_ = cmd.Run()
	}

	fmt.Fprintf(os.Stdout, "Created config file: %s\nPlease read this file for advanced configuration information.\n", confPath)
	return confPath, nil
}

func parseYAMLConfig(data []byte) (*Config, error) {
	cfg := &Config{
		Style:     "monokai",
		Formatter: "terminal256",
		Pager:     "cat",
	}

	lines := strings.Split(string(data), "\n")
	var currentCP *Cheatpath

	for _, line := range lines {
		rawLine := line
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		if strings.HasPrefix(line, "- name:") {
			if currentCP != nil {
				cfg.Cheatpaths = append(cfg.Cheatpaths, *currentCP)
			}
			currentCP = &Cheatpath{}
			val := strings.TrimSpace(strings.TrimPrefix(line, "- name:"))
			currentCP.Name = unquoteYAML(val)
			continue
		}

		if currentCP != nil {
			if strings.HasPrefix(line, "path:") {
				val := strings.TrimSpace(strings.TrimPrefix(line, "path:"))
				currentCP.Path = unquoteYAML(val)
				continue
			}
			if strings.HasPrefix(line, "readonly:") {
				val := strings.TrimSpace(strings.TrimPrefix(line, "readonly:"))
				currentCP.Readonly = (val == "true")
				continue
			}
			if strings.HasPrefix(line, "tags:") {
				val := strings.TrimSpace(strings.TrimPrefix(line, "tags:"))
				currentCP.Tags = parseYAMLArray(val)
				continue
			}
		}

		// Config level options
		if strings.HasPrefix(line, "editor:") {
			val := strings.TrimSpace(strings.TrimPrefix(line, "editor:"))
			cfg.Editor = unquoteYAML(val)
		} else if strings.HasPrefix(line, "colorize:") {
			val := strings.TrimSpace(strings.TrimPrefix(line, "colorize:"))
			cfg.Colorize = (val == "true")
		} else if strings.HasPrefix(line, "style:") {
			val := strings.TrimSpace(strings.TrimPrefix(line, "style:"))
			cfg.Style = unquoteYAML(val)
		} else if strings.HasPrefix(line, "formatter:") {
			val := strings.TrimSpace(strings.TrimPrefix(line, "formatter:"))
			cfg.Formatter = unquoteYAML(val)
		} else if strings.HasPrefix(line, "pager:") {
			val := strings.TrimSpace(strings.TrimPrefix(line, "pager:"))
			cfg.Pager = unquoteYAML(val)
		} else if strings.HasPrefix(line, "cheatpaths:") {
			// Start of cheatpaths list
		} else {
			// Check for syntax errors like invalid mapping
			if strings.Contains(line, ": [") && !strings.Contains(line, "]") {
				return nil, fmt.Errorf("yaml: mapping values are not allowed in this context")
			}
			_ = rawLine
		}
	}

	if currentCP != nil {
		cfg.Cheatpaths = append(cfg.Cheatpaths, *currentCP)
	}

	return cfg, nil
}

func unquoteYAML(s string) string {
	s = strings.TrimSpace(s)
	if (strings.HasPrefix(s, "\"") && strings.HasSuffix(s, "\"")) ||
		(strings.HasPrefix(s, "'") && strings.HasSuffix(s, "'")) {
		return s[1 : len(s)-1]
	}
	return s
}

func parseYAMLArray(s string) []string {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
		inner := s[1 : len(s)-1]
		parts := strings.Split(inner, ",")
		var res []string
		for _, p := range parts {
			p = unquoteYAML(strings.TrimSpace(p))
			if p != "" {
				res = append(res, p)
			}
		}
		return res
	}
	if s != "" {
		return []string{unquoteYAML(s)}
	}
	return nil
}

func expandPath(path string) string {
	if strings.HasPrefix(path, "~/") || path == "~" {
		home := getHomeDir()
		if path == "~" {
			return home
		}
		return filepath.Join(home, path[2:])
	}
	return os.ExpandEnv(path)
}

func addDirectoryScopedCheatpath(cfg *Config) {
	cwd, err := os.Getwd()
	if err != nil {
		return
	}

	dir := cwd
	for {
		cheatDir := filepath.Join(dir, ".cheat")
		if info, err := os.Stat(cheatDir); err == nil && info.IsDir() {
			cfg.Cheatpaths = append(cfg.Cheatpaths, Cheatpath{
				Name:     "cwd",
				Path:     cheatDir,
				Readonly: false,
			})
			break
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
}

func loadCheatsheets(cfg *Config) ([]Cheatsheet, error) {
	var sheets []Cheatsheet

	for _, cp := range cfg.Cheatpaths {
		cpPath := cp.Path
		err := filepath.Walk(cpPath, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return err
			}

			rel, err := filepath.Rel(cpPath, path)
			if err != nil {
				return nil
			}

			// Skip hidden files/dirs
			parts := strings.Split(rel, string(filepath.Separator))
			for _, p := range parts {
				if strings.HasPrefix(p, ".") && p != "." {
					if info.IsDir() {
						return filepath.SkipDir
					}
					return nil
				}
			}

			if info.IsDir() {
				return nil
			}

			content, err := os.ReadFile(path)
			if err != nil {
				return fmt.Errorf("failed to read file: %s, %w", rel, err)
			}

			fm, body, parseErr := parseFrontmatter(content)
			if parseErr != nil {
				return fmt.Errorf("failed to parse front-matter: %w", parseErr)
			}

			// Merge tags
			tagMap := make(map[string]bool)
			for _, t := range cp.Tags {
				tagMap[t] = true
			}
			for _, t := range fm.Tags {
				tagMap[t] = true
			}
			var tags []string
			for t := range tagMap {
				tags = append(tags, t)
			}
			sort.Strings(tags)

			title := filepath.ToSlash(rel)

			sheet := Cheatsheet{
				Title:    title,
				FilePath: path,
				PathName: cp.Name,
				Tags:     tags,
				Readonly: cp.Readonly,
				Syntax:   fm.Syntax,
				Body:     body,
				RawBody:  string(content),
			}
			sheets = append(sheets, sheet)
			return nil
		})

		if err != nil {
			return nil, fmt.Errorf("failed to load cheatsheets: %w", err)
		}
	}

	return sheets, nil
}

func parseFrontmatter(data []byte) (*Frontmatter, string, error) {
	str := string(data)
	if !strings.HasPrefix(str, "---\n") && !strings.HasPrefix(str, "---\r\n") {
		return &Frontmatter{}, str, nil
	}

	var delimiter string
	if strings.HasPrefix(str, "---\r\n") {
		delimiter = "---\r\n"
	} else {
		delimiter = "---\n"
	}

	rest := str[len(delimiter):]
	endIdx := strings.Index(rest, delimiter)
	if endIdx == -1 {
		if strings.HasSuffix(rest, "---") || strings.HasSuffix(rest, "---\r") {
			// Handles closing --- at EOF without newline
			endIdx = strings.LastIndex(rest, "---")
		} else {
			return nil, "", fmt.Errorf("failed to delimit frontmatter")
		}
	}

	fmStr := rest[:endIdx]
	body := rest[endIdx+len(delimiter):]

	fm := &Frontmatter{}
	lines := strings.Split(fmStr, "\n")
	for _, l := range lines {
		l = strings.TrimSpace(l)
		if l == "" || strings.HasPrefix(l, "#") {
			continue
		}
		if strings.HasPrefix(l, "syntax:") {
			fm.Syntax = unquoteYAML(strings.TrimSpace(strings.TrimPrefix(l, "syntax:")))
		} else if strings.HasPrefix(l, "tags:") {
			val := strings.TrimSpace(strings.TrimPrefix(l, "tags:"))
			if val != "" && !strings.HasPrefix(val, "[") {
				// String tag instead of slice
				return nil, "", fmt.Errorf("failed to unmarshal frontmatter: yaml: unmarshal errors:\n  line 2: cannot unmarshal !!str `%s` into []string", val)
			}
			fm.Tags = parseYAMLArray(val)
		}
	}

	return fm, body, nil
}

func handleCompletion(shell string) error {
	switch shell {
	case "bash":
		fmt.Print(bashCompletionScript)
		return nil
	case "zsh":
		fmt.Print(zshCompletionScript)
		return nil
	case "fish":
		fmt.Print(fishCompletionScript)
		return nil
	case "powershell":
		fmt.Print(powershellCompletionScript)
		return nil
	default:
		return &ExitError{Code: 1, Message: fmt.Sprintf("unsupported shell: %s (valid: bash, zsh, fish, powershell)", shell), ToStderr: true}
	}
}

func handleCobraComplete(args []string) error {
	cfg, err := loadConfig()
	if err != nil {
		fmt.Println(":4")
		fmt.Println("Completion ended with directive: ShellCompDirectiveNoFileComp")
		return nil
	}

	sheets, _ := loadCheatsheets(cfg)
	titleMap := make(map[string]bool)
	for _, s := range sheets {
		titleMap[s.Title] = true
	}

	var titles []string
	for t := range titleMap {
		titles = append(titles, t)
	}
	sort.Strings(titles)

	for _, t := range titles {
		fmt.Println(t)
	}
	fmt.Println(":4")
	fmt.Println("Completion ended with directive: ShellCompDirectiveNoFileComp")
	return nil
}

func printDirectories(cfg *Config, opts *Options) error {
	out := getWriter(cfg, opts, false)
	defer out.Close()

	w := tabwriter.NewWriter(out.w, 1, 0, 1, ' ', 0)
	for _, cp := range cfg.Cheatpaths {
		fmt.Fprintf(w, "%s:\t%s\n", cp.Name, cp.Path)
	}
	w.Flush()
	return nil
}

func printTags(sheets []Cheatsheet, cfg *Config, opts *Options) error {
	tagMap := make(map[string]bool)
	for _, s := range sheets {
		for _, t := range s.Tags {
			tagMap[t] = true
		}
	}

	var tags []string
	for t := range tagMap {
		tags = append(tags, t)
	}
	sort.Strings(tags)

	out := getWriter(cfg, opts, false)
	defer out.Close()

	for _, t := range tags {
		fmt.Fprintln(out.w, t)
	}
	return nil
}

func printList(sheets []Cheatsheet, opts *Options, args []string, cfg *Config) error {
	var filtered []Cheatsheet

	filterTerm := ""
	if len(args) > 0 {
		filterTerm = strings.ToLower(args[0])
	}

	for _, s := range sheets {
		if opts.path != "" && s.PathName != opts.path {
			continue
		}
		if opts.tag != "" && !hasTag(s.Tags, opts.tag) {
			continue
		}
		if filterTerm != "" && !strings.Contains(strings.ToLower(s.Title), filterTerm) {
			continue
		}
		filtered = append(filtered, s)
	}

	// Validate path filter if specified
	if opts.path != "" {
		foundPath := false
		for _, cp := range cfg.Cheatpaths {
			if cp.Name == opts.path {
				foundPath = true
				break
			}
		}
		if !foundPath {
			return &ExitError{Code: 1, Message: fmt.Sprintf("invalid option --path: cheatpath does not exist: %s", opts.path), ToStderr: true}
		}
	}

	if len(filtered) == 0 {
		return &ExitError{Code: 2, Message: "", ToStderr: false}
	}

	out := getWriter(cfg, opts, false)
	defer out.Close()

	w := tabwriter.NewWriter(out.w, 1, 0, 1, ' ', 0)
	if opts.brief {
		fmt.Fprintln(w, "title:\ttags:")
		for _, s := range filtered {
			tagsStr := strings.Join(s.Tags, ",")
			fmt.Fprintf(w, "%s\t%s\n", s.Title, tagsStr)
		}
	} else {
		fmt.Fprintln(w, "title:\tfile:\ttags:")
		for _, s := range filtered {
			tagsStr := strings.Join(s.Tags, ",")
			fmt.Fprintf(w, "%s\t%s\t%s\n", s.Title, s.FilePath, tagsStr)
		}
	}
	w.Flush()
	return nil
}

func formatMultiSheet(sheets []Cheatsheet, shouldColorize bool, cfg *Config) string {
	var buf bytes.Buffer
	for i, s := range sheets {
		if i > 0 {
			buf.WriteString("\n")
		}
		if shouldColorize {
			fmt.Fprintf(&buf, "%s \x1b[2m(%s)\x1b[0m\n", s.Title, s.PathName)
		} else {
			fmt.Fprintf(&buf, "%s (%s)\n", s.Title, s.PathName)
		}

		lines := strings.Split(s.Body, "\n")
		for j, l := range lines {
			if j == len(lines)-1 && l == "" {
				continue
			}
			if shouldColorize {
				l = colorizeLine(l, s.Syntax, cfg)
			}
			fmt.Fprintf(&buf, "\t%s\n", l)
		}
	}
	return buf.String()
}

func handleSearch(sheets []Cheatsheet, opts *Options, cfg *Config) error {
	pattern := opts.search
	if !opts.regex {
		pattern = "(?i)" + pattern
	}

	re, err := regexp.Compile(pattern)
	if err != nil {
		return &ExitError{Code: 1, Message: fmt.Sprintf("failed to compile regexp: %s, %v", pattern, err), ToStderr: true}
	}

	if opts.path != "" {
		foundPath := false
		for _, cp := range cfg.Cheatpaths {
			if cp.Name == opts.path {
				foundPath = true
				break
			}
		}
		if !foundPath {
			return &ExitError{Code: 1, Message: fmt.Sprintf("invalid option --path: cheatpath does not exist: %s", opts.path), ToStderr: true}
		}
	}

	var matched []Cheatsheet
	for _, s := range sheets {
		if opts.path != "" && s.PathName != opts.path {
			continue
		}
		if opts.tag != "" && !hasTag(s.Tags, opts.tag) {
			continue
		}
		if re.MatchString(s.Body) {
			matched = append(matched, s)
		}
	}

	if len(matched) == 0 {
		return nil
	}

	shouldColorize := opts.colorize || cfg.Colorize

	out := getWriter(cfg, opts, false)
	defer out.Close()

	outStr := formatMultiSheet(matched, shouldColorize, cfg)
	outStr = strings.TrimSuffix(outStr, "\n")
	fmt.Fprint(out.w, outStr)
	return nil
}

func handleView(sheets []Cheatsheet, targetTitle string, opts *Options, cfg *Config) error {
	if opts.path != "" {
		foundPath := false
		for _, cp := range cfg.Cheatpaths {
			if cp.Name == opts.path {
				foundPath = true
				break
			}
		}
		if !foundPath {
			return &ExitError{Code: 1, Message: fmt.Sprintf("invalid option --path: cheatpath does not exist: %s", opts.path), ToStderr: true}
		}
	}

	var matched []Cheatsheet
	for _, s := range sheets {
		if s.Title == targetTitle {
			if opts.path != "" && s.PathName != opts.path {
				continue
			}
			if opts.tag != "" && !hasTag(s.Tags, opts.tag) {
				continue
			}
			matched = append(matched, s)
		}
	}

	if len(matched) == 0 {
		return &ExitError{Code: 2, Message: fmt.Sprintf("No cheatsheet found for '%s'.", targetTitle), ToStderr: false}
	}

	shouldColorize := opts.colorize || cfg.Colorize
	out := getWriter(cfg, opts, false)
	defer out.Close()

	if opts.all {
		outStr := formatMultiSheet(matched, shouldColorize, cfg)
		fmt.Fprint(out.w, outStr)
	} else {
		// Single sheet (most local match)
		sheet := matched[len(matched)-1]
		if shouldColorize {
			lines := strings.Split(sheet.Body, "\n")
			for i, l := range lines {
				if i == len(lines)-1 && l == "" {
					continue
				}
				fmt.Fprintln(out.w, colorizeLine(l, sheet.Syntax, cfg))
			}
		} else {
			fmt.Fprint(out.w, sheet.Body)
		}
	}

	return nil
}

func handleEdit(cfg *Config, sheets []Cheatsheet, title string, pathFilter string) error {
	editor := getEditor(cfg)
	if editor == "" {
		return &ExitError{Code: 1, Message: "failed to load config: no editor set", ToStderr: true}
	}

	var targetPath string

	if pathFilter != "" {
		var targetCP *Cheatpath
		for _, cp := range cfg.Cheatpaths {
			if cp.Name == pathFilter {
				targetCP = &cp
				break
			}
		}
		if targetCP == nil {
			return &ExitError{Code: 1, Message: fmt.Sprintf("invalid option --path: cheatpath does not exist: %s", pathFilter), ToStderr: true}
		}
		if targetCP.Readonly {
			return &ExitError{Code: 1, Message: "failed to get writeable path: no writeable cheatpaths found", ToStderr: true}
		}
		targetPath = filepath.Join(targetCP.Path, filepath.FromSlash(title))
	} else {
		// Look if sheet exists
		var existing *Cheatsheet
		for _, s := range sheets {
			if s.Title == title {
				existing = &s
				break
			}
		}

		if existing != nil {
			if !existing.Readonly {
				targetPath = existing.FilePath
			} else {
				// Find last writeable cheatpath
				var writeableCP *Cheatpath
				for i := len(cfg.Cheatpaths) - 1; i >= 0; i-- {
					if !cfg.Cheatpaths[i].Readonly {
						writeableCP = &cfg.Cheatpaths[i]
						break
					}
				}
				if writeableCP == nil {
					return &ExitError{Code: 1, Message: "failed to get writeable path: no writeable cheatpaths found", ToStderr: true}
				}
				targetPath = filepath.Join(writeableCP.Path, filepath.FromSlash(title))
				// Copy existing sheet content
				os.MkdirAll(filepath.Dir(targetPath), 0755)
				os.WriteFile(targetPath, []byte(existing.RawBody), 0644)
			}
		} else {
			// Find last writeable cheatpath
			var writeableCP *Cheatpath
			for i := len(cfg.Cheatpaths) - 1; i >= 0; i-- {
				if !cfg.Cheatpaths[i].Readonly {
					writeableCP = &cfg.Cheatpaths[i]
					break
				}
			}
			if writeableCP == nil {
				return &ExitError{Code: 1, Message: "failed to get writeable path: no writeable cheatpaths found", ToStderr: true}
			}
			targetPath = filepath.Join(writeableCP.Path, filepath.FromSlash(title))
		}
	}

	os.MkdirAll(filepath.Dir(targetPath), 0755)

	// Execute editor
	cmdParts := strings.Fields(editor)
	cmdName := cmdParts[0]
	cmdArgs := append(cmdParts[1:], targetPath)

	cmd := exec.Command(cmdName, cmdArgs...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		return &ExitError{Code: 1, Message: err.Error(), ToStderr: true}
	}
	return nil
}

func handleRm(cfg *Config, sheets []Cheatsheet, title string, pathFilter string) error {
	if pathFilter != "" {
		var targetCP *Cheatpath
		for _, cp := range cfg.Cheatpaths {
			if cp.Name == pathFilter {
				targetCP = &cp
				break
			}
		}
		if targetCP == nil {
			return &ExitError{Code: 1, Message: fmt.Sprintf("invalid option --path: cheatpath does not exist: %s", pathFilter), ToStderr: true}
		}

		var targetSheet *Cheatsheet
		for _, s := range sheets {
			if s.Title == title && s.PathName == pathFilter {
				targetSheet = &s
				break
			}
		}

		if targetSheet == nil {
			return &ExitError{Code: 2, Message: fmt.Sprintf("No cheatsheet found for '%s'.", title), ToStderr: true}
		}

		if targetSheet.Readonly {
			return &ExitError{Code: 1, Message: fmt.Sprintf("cheatsheet '%s' is read-only.", title), ToStderr: true}
		}

		os.Remove(targetSheet.FilePath)
		return nil
	}

	// No path filter specified
	var matches []Cheatsheet
	for _, s := range sheets {
		if s.Title == title {
			matches = append(matches, s)
		}
	}

	if len(matches) == 0 {
		return &ExitError{Code: 2, Message: fmt.Sprintf("No cheatsheet found for '%s'.", title), ToStderr: true}
	}

	mostLocal := matches[len(matches)-1]
	if mostLocal.Readonly {
		return &ExitError{Code: 1, Message: fmt.Sprintf("cheatsheet '%s' is read-only.", title), ToStderr: true}
	}

	os.Remove(mostLocal.FilePath)
	return nil
}

func handleUpdate(cfg *Config, opts *Options) error {
	var targetCPs []Cheatpath

	if opts.path != "" {
		found := false
		for _, cp := range cfg.Cheatpaths {
			if cp.Name == opts.path {
				targetCPs = append(targetCPs, cp)
				found = true
				break
			}
		}
		if !found {
			return &ExitError{Code: 1, Message: fmt.Sprintf("invalid option --path: cheatpath does not exist: %s", opts.path), ToStderr: true}
		}
	} else {
		targetCPs = cfg.Cheatpaths
	}

	hasErr := false
	for _, cp := range targetCPs {
		gitDir := filepath.Join(cp.Path, ".git")
		if _, err := os.Stat(gitDir); err != nil {
			fmt.Printf("%s: skipped (not a git repository)\n", cp.Name)
			continue
		}

		cmd := exec.Command("git", "-C", cp.Path, "pull")
		out, err := cmd.CombinedOutput()
		if err != nil {
			errStr := strings.TrimSpace(string(out))
			if errStr == "" {
				errStr = err.Error()
			}
			if strings.Contains(errStr, "No remote repository specified") || strings.Contains(errStr, "no tracking information") {
				errStr = "remote not found"
			}
			fmt.Printf("%s: error (%s)\n", cp.Name, errStr)
			hasErr = true
		} else {
			fmt.Printf("%s: ok\n", cp.Name)
		}
	}

	if hasErr {
		return &ExitError{Code: 1, Message: "", ToStderr: false}
	}
	return nil
}

func getEditor(cfg *Config) string {
	if v := os.Getenv("VISUAL"); v != "" {
		return v
	}
	if e := os.Getenv("EDITOR"); e != "" {
		return e
	}
	if cfg.Editor != "" && cfg.Editor != "EDITOR_PATH" {
		return cfg.Editor
	}
	return ""
}

func hasTag(tags []string, tag string) bool {
	for _, t := range tags {
		if t == tag {
			return true
		}
	}
	return false
}

type PagerWriter struct {
	w   io.Writer
	cmd *exec.Cmd
}

func (p *PagerWriter) Close() {
	if p.cmd != nil {
		if pipe, ok := p.w.(io.WriteCloser); ok {
			pipe.Close()
		}
		p.cmd.Wait()
	}
}

func getWriter(cfg *Config, opts *Options, isInit bool) *PagerWriter {
	if isInit || cfg.Pager == "" || cfg.Pager == "cat" {
		return &PagerWriter{w: os.Stdout}
	}

	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "sh"
	}

	cmd := exec.Command(shell, "-c", cfg.Pager)
	pipe, err := cmd.StdinPipe()
	if err != nil {
		return &PagerWriter{w: os.Stdout}
	}

	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		return &PagerWriter{w: os.Stdout}
	}

	return &PagerWriter{w: pipe, cmd: cmd}
}

func colorizeLine(line string, syntax string, cfg *Config) string {
	trimmed := strings.TrimSpace(line)
	if strings.HasPrefix(trimmed, "#") {
		if cfg.Formatter == "terminal256" {
			return "\x1b[38;5;242m" + line + "\x1b[0m\x1b[38;5;231m\x1b[0m"
		}
		return "\x1b[3m" + line + "\x1b[0m"
	}
	if cfg.Formatter == "terminal256" {
		return formatTerminal256(line)
	}
	return line
}

func formatTerminal256(line string) string {
	if line == "" {
		return ""
	}
	var res strings.Builder
	inQuote := false
	quoteChar := byte(0)
	var current strings.Builder

	for i := 0; i < len(line); i++ {
		ch := line[i]
		if inQuote {
			current.WriteByte(ch)
			if ch == quoteChar {
				res.WriteString("\x1b[38;5;186m" + current.String() + "\x1b[0m")
				current.Reset()
				inQuote = false
			}
		} else if ch == '"' || ch == '\'' {
			if current.Len() > 0 {
				res.WriteString("\x1b[38;5;231m" + current.String() + "\x1b[0m")
				current.Reset()
			}
			inQuote = true
			quoteChar = ch
			current.WriteByte(ch)
		} else {
			current.WriteByte(ch)
		}
	}
	if current.Len() > 0 {
		if inQuote {
			res.WriteString("\x1b[38;5;186m" + current.String() + "\x1b[0m")
		} else {
			res.WriteString("\x1b[38;5;231m" + current.String() + "\x1b[0m")
		}
	}
	return res.String()
}

